#!/bin/bash

#####################################################
# QUICK START GUIDE FOR NEW RASPBERRY PI
#####################################################

# This file contains all the commands you need to set up
# the RDK Device Manager on a new Raspberry Pi

echo "=========================================="
echo "RDK Device Manager - Quick Start"
echo "=========================================="
echo ""
echo "Follow these steps to install on a new Raspberry Pi:"
echo ""
echo "STEP 1: Copy this backup folder to your new Raspberry Pi"
echo "  You can use:"
echo "  - USB stick (copy the entire folder)"
echo "  - SCP: scp -r RDK_Device_Manager_Backup_* pi@<new-pi-ip>:/home/pi/"
echo "  - rsync: rsync -avz RDK_Device_Manager_Backup_* pi@<new-pi-ip>:/home/pi/"
echo ""
echo "STEP 2: Navigate to the backup folder"
echo "  cd ~/RDK_Device_Manager_Backup_*"
echo ""
echo "STEP 3: Make the installation script executable"
echo "  chmod +x install_complete_system.sh"
echo ""
echo "STEP 4: Run the installation script"
echo "  ./install_complete_system.sh"
echo ""
echo "STEP 5: Copy configuration and data files"
echo "  cp -r app/* ./"
echo "  cp config/* ./"
echo "  cp data/* ./"
echo ""
echo "STEP 6: Activate the virtual environment"
echo "  source venv/bin/activate"
echo ""
echo "STEP 7: Start the application"
echo "  python3 app.py"
echo ""
echo "STEP 8: Access the application"
echo "  Open browser: http://localhost:5000"
echo "  Or from another device: http://<raspberry-pi-ip>:5000"
echo ""
echo "=========================================="
echo "Production Deployment"
echo "=========================================="
echo ""
echo "For production use with systemd service:"
echo "  sudo bash install_service.sh"
echo "  sudo systemctl enable device-testing"
echo "  sudo systemctl start device-testing"
echo ""
echo "=========================================="
echo "Troubleshooting"
echo "=========================================="
echo ""
echo "If you encounter issues:"
echo "  1. Check Python version: python3 --version (need 3.7+)"
echo "  2. Verify Tesseract: tesseract --version"
echo "  3. Check logs: tail -f iteration_logs/*.log"
echo "  4. Test SSH connectivity to devices"
echo "  5. Verify devices.json has correct IP addresses"
echo ""
echo "=========================================="
echo "What's Included"
echo "=========================================="
echo ""
echo "/app/               - All application code"
echo "/config/            - Configuration files"
echo "/data/              - Devices, users, jobs data"
echo "/docs/              - Full documentation"
echo "requirements.txt    - Python dependencies"
echo "install_complete_system.sh - Main installer"
echo ""
echo "=========================================="

read -p "Press Enter to exit..."
